axes.moveTo([0, -0.3, 0]);
const curve = axes.plot(x => x * x, { color: BLUE, xRange: [0, 2] });
scene.add(axes, curve);

const f = x => x * x;
let rects = [];
let info = null;

function build(n) {
  for (const r of rects) scene.remove(r);
  rects = [];
  const dx = 2 / n;
  let sum = 0;
  for (let i = 1; i <= n; i++) {
    const x0 = (i - 1) * dx, x1 = i * dx;
    const h = f(x1);
    sum += h * dx;
    const p = new Polygon({
      vertices: [axes.c2p(x0, 0), axes.c2p(x1, 0), axes.c2p(x1, h), axes.c2p(x0, h)],
      color: YELLOW
    });
    p.setFill(YELLOW, 0.4);
    p.setStrokeWidth(n > 40 ? 0.5 : 2);
    rects.push(p);
    scene.add(p);
  }
  if (info) scene.remove(info);
  info = new Text({
    text: 'n = ' + n + '   Sum = ' + sum.toFixed(4) + '   Exact = 2.6667',
    color: WHITE, fontSize: 26
  });
  info.moveTo([0, 3.4, 0]);
  scene.add(info);
}

build(4);

const controls = new Controls(scene, { position: 'top-right' });
controls.addSlider({
  label: 'Rectangles', min: 1, max: 100, value: 4, step: 1,
  onChange: (v) => { build(Math.round(v)); }
